class Solution {
    public int minimumIndex(List<Integer> nums){
        int candidate=0,balance=0;
        for(int value:nums){
            if(balance==0)candidate=value;
            balance+=value==candidate?1:-1;
        }
        int total=0;
        for(int value:nums)if(value==candidate)total++;
        int prefix=0,n=nums.size();
        for(int i=0;i<n-1;i++){
            if(nums.get(i)==candidate)prefix++;
            if(prefix*2>i+1&&(total-prefix)*2>n-i-1)return i;
        }
        return -1;
    }
}

code.kotlin:
class Solution {
    fun minimumIndex(nums:List<Int>):Int{
        var candidate=0;
        var balance=0;
        for(value in nums){
            if(balance==0)candidate=value;
            balance+=if(value==candidate)1 else -1
        };
        val total=nums.count{
            it==candidate
        };
        var prefix=0;
        for(i in 0 until nums.lastIndex){
            if(nums[i]==candidate)prefix++;
            if(prefix*2>i+1&&(total-prefix)*2>nums.size-i-1)return i
        };
        return -1
    }
}

